import {
  Body,
  Box,
  Button,
  Heading,
  MainLayout,
  ModuleBox,
  useTheme,
} from "@norma/core";
import { InputPassword, InputText } from "@norma/form";
import { useState } from "react";
import { useNavigate } from "react-router-dom";

function Login() {
  const navigate = useNavigate();
  const { token } = useTheme();
  const [inputValue, setinputValue] = useState("");
  const [inputPassValue, setinputPassValue] = useState("");

  return (
    <MainLayout
      bg={`linear-gradient( to bottom, #f4f4f4 0%, #f4f4f4 60%,${token?.Color.primary} 60%,  ${token?.Color.primary} 100% );`}
      px="16px"
      height="100vh"
    >
      <MainLayout.Header
        justifyContent="center"
        alignItems="center"
        flexDirection="column"
        pt="44px"
      >
        <Box pb="24px">
          <img src="https://www.galicia.ar/content/dam/galicia/banco-galicia/recursos/logos/Logos-Bgcom-Galicia_Galicia-desktop%20taman%CC%83o%20esta%CC%81ndar.png" />
        </Box>
        <Body align="center">
          Por ahora solo disponible para cuentas Galicia.
          <br />
          Podés ingresar desde Online Banking o por acá si tenés Office Banking.
        </Body>
      </MainLayout.Header>
      <MainLayout.Content justifyContent="center" alignItems="center">
        <ModuleBox maxWidth="400px" mb="48px">
          <ModuleBox.Header justifyContent="center" mb="24px">
            <Heading element="h1" variant="s2" align="center">
              Entrar a mi cuenta
            </Heading>
          </ModuleBox.Header>
          <ModuleBox.Content>
            <InputText
              variant={"shadow"}
              labelText={"Usuario"}
              type="text"
              id="text"
              value={inputValue}
              onChange={(e) => {
                setinputValue(e.target.value);
              }}
            />
            <InputPassword
              variant={"shadow"}
              labelText={"Contraseña"}
              id="password"
              value={inputPassValue}
              onChange={(e) => {
                setinputPassValue(e.target.value);
              }}
            />
          </ModuleBox.Content>
          <ModuleBox.Footer
            justifyContent="center"
            alignItems="center"
            flexDirection="column"
            pt="24px"
          >
            <Button
              variant="primary"
              size="regular"
              fullwidth
              onClick={() => {
                localStorage.setItem("isAuthenticated", "true");
                navigate("/");
              }}
            >
              Ingresar
            </Button>
            <Button variant="terciary" size="regular" fullwidth>
              Recuperar Password
            </Button>
          </ModuleBox.Footer>
        </ModuleBox>
        <Body color="white" align="center" variant="s7">
          ¿Querés generar usuarios para otras personas de tu negocio?
          <br />
          Te explicamos cómo hacerlo desde Office Banking.
        </Body>
      </MainLayout.Content>
      <MainLayout.Footer
        justifyContent="center"
        alignItems="center"
        pt="24px"
        borderTop="1px solid white"
      >
        <Body color="white" align="center" variant="s7">
          Si querés tener una cuenta, adherí tu comercio en Galicia Comercios.
        </Body>
      </MainLayout.Footer>
    </MainLayout>
  );
}

export default Login;
