import { useWindowSize, MainLayout, Flex, useTheme } from "@norma/core";
import Topbar from "./components/Topbar";
import Navbar from "./components/Navbar";

const LayoutPage = ({ children }: any) => {
  const { token } = useTheme();
  const { isDown } = useWindowSize();
  const md = isDown("md");
  return (
    <>
      <Navbar />
      <Flex
        justifyContent="center"
        minHeight="100vh"
        bgColor={token?.Color.grey20} //"grey20"
        pt="47px"
        ml={!md ? "230px" : "0px"}
      >
        <MainLayout maxW="1500px" w="100%" px="16px" pt={"16px"}>
          <MainLayout.Header>{/* <Topbar /> */}</MainLayout.Header>
          <MainLayout.Content>{children}</MainLayout.Content>
        </MainLayout>
      </Flex>
    </>
  );
};

export default LayoutPage;
