import { FeedBackLayout, ModuleBox } from "@norma/core";
import { Illustrations } from "@norma/icons";
import { NavigateFunction, useNavigate } from "react-router-dom";

const getBotonera = (navigate: NavigateFunction) => [
  {
    onClick: () => navigate(0),
    text: "Volver a cargar",
    // variant: "primary",
  },
  {
    onClick: () => navigate("/"),
    text: "Volver al inicio",
    variant: "secondary",
  },
];

const FeedbackPage401 = () => {
  const navigate = useNavigate();
  return (
    <ModuleBox h="100%">
      <ModuleBox.Content overflow="visible">
        <FeedBackLayout
          typeIcon={<Illustrations size="sm" type="SeguroHogar" />}
          mainTitle="Role no autorizado"
          description="No tienes permisos para acceder a esta sección."
          errorCode="401"
          btnList={getBotonera(navigate)}
        />
      </ModuleBox.Content>
    </ModuleBox>
  );
};

export default FeedbackPage401;
