import { BrowserRouter, Route, Routes, useLocation } from "react-router-dom";
import { AuthGuard } from "../guards";
import { PrivateRoutes, PublicRoutes } from "../routes";
import { Home, FeedbackPage401, Login } from "../pages";
import { PrivateLayout, PublicLayout } from "../layouts";
import { ErrorBoundary } from "react-error-boundary";
import DynamicRemote from "../components/DynamicRemote/DynamicRemote";
import NotFound from "../pages/NotFound/NotFound";

function Router() {
  const isDev = process.env.NODE_ENV === "development";
  const browserRouterProps = !isDev ? { basename: "/host-mf-app" } : {};
  console.log({ isDev, browserRouterProps });

  return (
    <BrowserRouter {...browserRouterProps}>
      <ErrorBoundary
        fallback={
          <span style={{ color: "blue" }}>Error, acá pasó algo papu!</span>
        }
      >
        <Routes>
          <Route element={<PublicLayout />}>
            <Route path={PublicRoutes.LOGIN} element={<Login />} />
          </Route>

          <Route element={<PrivateLayout />}>
            <Route path={PublicRoutes.HOME} element={<Home />} />
            <Route path={PublicRoutes.FEEDBACK} element={<FeedbackPage401 />} />

            <Route element={<AuthGuard />}>
              <Route
                path={PrivateRoutes.REMOTE_ROUTER}
                element={<DynamicRemote request="remote_rspack/RemoteRouter" />}
              />

              <Route
                path={PrivateRoutes.REMOTE_ROUTER_CYP}
                element={
                  <DynamicRemote request="remote_cyp_rspack/RemoteCyPRouter" />
                }
              />

              <Route
                path={"/prueba"}
                element={<DynamicRemote request="remote_webpack/TestA" />}
              />
            </Route>
          </Route>
          <Route path="*" element={<NotFound />} />
        </Routes>
      </ErrorBoundary>
    </BrowserRouter>
  );
}

export default Router;
